Reported-by: Alexander Potapenko <glider@google.com>
Fixes: a7800aa80ea4 ("KVM: Add KVM_CREATE_GUEST_MEMFD ioctl() for guest-specific backing memory")
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20251202020334.1171351-2-seanjc@google.com
Signed-off-by: Sean Christopherson <seanjc@google.com>

Here is the root cause:
KVM allowed userspace to clear the KVM_MEM_GUEST_MEMFD flag on an existing memslot via a KVM_SET_USER_MEMORY_REGION ioctl with only flags changed, but did not unbind from the associated guest_memfd. This leaves the memslot referencing a freed guest_memfd after that file is released, resulting in a use-after-free.

Here is the patch:

 static int kvm_set_memory_region(struct kvm *kvm,
 				 const struct kvm_userspace_memory_region2 *mem)
 {
 	struct kvm_memory_slot *old, *new;
 	struct kvm_memslots *slots;
 	enum kvm_mr_change change;
 	unsigned long npages;
 	gfn_t base_gfn;
 	int as_id, id;
 	int r;

 	lockdep_assert_held(&kvm->slots_lock);

 	r = check_memory_region_flags(kvm, mem);
 	if (r)
 		return r;

 	as_id = mem->slot >> 16;
 	id = (u16)mem->slot;

 	/* General sanity checks */
 	if ((mem->memory_size & (PAGE_SIZE - 1)) ||
 	    (mem->memory_size != (unsigned long)mem->memory_size))
 		return -EINVAL;
 	if (mem->guest_phys_addr & (PAGE_SIZE - 1))
 		return -EINVAL;
 	/* We can read the guest memory with __xxx_user() later on. */
 	if ((mem->userspace_addr & (PAGE_SIZE - 1)) ||
 	    (mem->userspace_addr != untagged_addr(mem->userspace_addr)) ||
 	     !access_ok((void __user *)(unsigned long)mem->userspace_addr,
 			mem->memory_size))
 		return -EINVAL;
 	if (mem->flags & KVM_MEM_GUEST_MEMFD &&
 	    (mem->guest_memfd_offset & (PAGE_SIZE - 1) ||
 	     mem->guest_memfd_offset + mem->memory_size < mem->guest_memfd_offset))
 		return -EINVAL;
 	if (as_id >= kvm_arch_nr_memslot_as_ids(kvm) || id >= KVM_MEM_SLOTS_NUM)
 		return -EINVAL;
 	if (mem->guest_phys_addr + mem->memory_size < mem->guest_phys_addr)
 		return -EINVAL;

 	/*
 	 * The size of userspace-defined memory regions is restricted in order
 	 * to play nice with dirty bitmap operations, which are indexed with an
 	 * "unsigned int".  KVM's internal memory regions don't support dirty
 	 * logging, and so are exempt.
 	 */
 	if (id < KVM_USER_MEM_SLOTS &&
 	    (mem->memory_size >> PAGE_SHIFT) > KVM_MEM_MAX_NR_PAGES)
 		return -EINVAL;

 	slots = __kvm_memslots(kvm, as_id);

 	/*
 	 * Note, the old memslot (and the pointer itself!) may be invalidated
 	 * and/or destroyed by kvm_set_memslot().
 	 */
 	old = id_to_memslot(slots, id);

 	if (!mem->memory_size) {
 		if (!old || !old->npages)
 			return -EINVAL;

 		if (WARN_ON_ONCE(kvm->nr_memslot_pages < old->npages))
 			return -EIO;

 		return kvm_set_memslot(kvm, old, NULL, KVM_MR_DELETE);
 	}

 	base_gfn = (mem->guest_phys_addr >> PAGE_SHIFT);
 	npages = (mem->memory_size >> PAGE_SHIFT);

 	if (!old || !old->npages) {
 		change = KVM_MR_CREATE;

 		/*
 		 * To simplify KVM internals, the total number of pages across
 		 * all memslots must fit in an unsigned long.
 		 */
 		if ((kvm->nr_memslot_pages + npages) < kvm->nr_memslot_pages)
 			return -EINVAL;
 	} else { /* Modify an existing slot. */
 		/* Private memslots are immutable, they can only be deleted. */
 		if (mem->flags & KVM_MEM_GUEST_MEMFD)
 			return -EINVAL;
 		if ((mem->userspace_addr != old->userspace_addr) ||
 		    (npages != old->npages) ||
-		    ((mem->flags ^ old->flags) & KVM_MEM_READONLY))
+		    ((mem->flags ^ old->flags) & (KVM_MEM_READONLY | KVM_MEM_GUEST_MEMFD)))
 			return -EINVAL;

 		if (base_gfn != old->base_gfn)
 			change = KVM_MR_MOVE;
 		else if (mem->flags != old->flags)
 			change = KVM_MR_FLAGS_ONLY;
 		else /* Nothing to change. */
 			return 0;
 	}

 	if ((change == KVM_MR_CREATE || change == KVM_MR_MOVE) &&
 	    kvm_check_memslot_overlap(slots, id, base_gfn, base_gfn + npages))
 		return -EEXIST;

 	/* Allocate a slot that will persist in the memslot. */
 	new = kzalloc(sizeof(*new), GFP_KERNEL_ACCOUNT);
 	if (!new)
 		return -ENOMEM;

 	new->as_id = as_id;
 	new->id = id;
 	new->base_gfn = base_gfn;
 	new->npages = npages;
 	new->flags = mem->flags;
 	new->userspace_addr = mem->userspace_addr;
 	if (mem->flags & KVM_MEM_GUEST_MEMFD) {
 		r = kvm_gmem_bind(kvm, new, mem->guest_memfd, mem->guest_memfd_offset);
 		if (r)
 			goto out;
 	}

 	r = kvm_set_memslot(kvm, old, new, change);
 	if (r)
 		goto out_unbind;

 	return 0;

 out_unbind:
 	if (mem->flags & KVM_MEM_GUEST_MEMFD)
 		kvm_gmem_unbind(new);
 out:
 	kfree(new);
 	return r;
 }



